"""Pure artifact parser tests: no Java, shared-library loading, or sockets."""

import unittest

from check_android_jni_exports import check_exports, declared_symbols, exported_symbols


HEADER = """
/* Generated by javac. JNIEXPORT ignored comment example. */
JNIEXPORT jlong JNICALL Java_dev_capyio_android_AndroidNativeCatalogRuntime_nativeCreate
  (JNIEnv *, jclass, jstring);
JNIEXPORT jbyteArray JNICALL Java_dev_capyio_android_AndroidNativeCatalogRuntime_nativeAudioUse
  (JNIEnv *, jclass, jlong, jstring, jstring, jstring, jstring, jint);
"""
CREATE = "Java_dev_capyio_android_AndroidNativeCatalogRuntime_nativeCreate"
AUDIO = "Java_dev_capyio_android_AndroidNativeCatalogRuntime_nativeAudioUse"
SYMBOLS = f"0000000000012340 T {CREATE}\n0000000000012350 T {AUDIO}\n"


class AndroidJniExportTests(unittest.TestCase):
    def test_generated_header_matches_defined_exports_and_allows_other_classes(self):
        self.assertEqual(check_exports(HEADER, SYMBOLS + "00001236 T Java_other_nativeMethod\n"), 2)

    def test_missing_native_method_fails(self):
        with self.assertRaisesRegex(ValueError, "missing defined JNI.*nativeAudioUse"):
            check_exports(HEADER, f"00001234 T {CREATE}\n")

    def test_undefined_data_and_local_symbols_do_not_satisfy_native_declarations(self):
        for kind in ("U", "D", "B", "t", "w"):
            with self.subTest(kind=kind), self.assertRaises(ValueError):
                check_exports(HEADER, f"00001234 T {CREATE}\n00001235 {kind} {AUDIO}\n")

    def test_weak_function_is_a_defined_export(self):
        self.assertEqual(check_exports(HEADER, SYMBOLS.replace(" T ", " W ")), 2)

    def test_empty_comment_only_or_malformed_header_fails(self):
        for text in ("", "/* JNIEXPORT jint JNICALL Java_fake (JNIEnv*); */", HEADER + "JNIEXPORT invalid;"):
            with self.subTest(text=text), self.assertRaises(ValueError):
                declared_symbols(text)

    def test_duplicate_declaration_or_export_fails(self):
        with self.assertRaisesRegex(ValueError, "duplicate JNI declarations"):
            declared_symbols(HEADER + HEADER)
        with self.assertRaisesRegex(ValueError, "duplicate JNI function exports"):
            exported_symbols(SYMBOLS + SYMBOLS)

    def test_empty_or_non_function_listing_fails(self):
        for text in ("", "nm: file not found", f"                 U {CREATE}\n"):
            with self.subTest(text=text), self.assertRaises(ValueError):
                exported_symbols(text)


if __name__ == "__main__":
    unittest.main()
